#include <bits/stdc++.h>

#define loop(i, n) for (int i = 0; i < (n); ++i)
#define rev_loop(i, n) for (int i = (n) - 1; i >= 0; --i)

using namespace std;
using LL = long long;

struct FlowNetwork {
  struct Edge {
    int to;
    LL capacity;
    LL cost;
    int rev_idx;
  };

  vector<vector<Edge>> adj;

  FlowNetwork(int n) : adj(n) {}

  void connect(int u, int v, LL cap, LL w) {
    int u_rev = adj[u].size();
    int v_rev = adj[v].size();
    adj[u].push_back({v, cap, w, v_rev});
    adj[v].push_back({u, 0, -w, u_rev});
  }

  LL min_cost_flow(int s, int t, LL flow_req) {
    LL total_cost = 0;
    int n = adj.size();
    vector<LL> dist(n), potential(n);
    vector<int> parent(n), parent_edge(n);
    const LL INF = 1e18;
    while (flow_req > 0) {
      fill(dist.begin(), dist.end(), INF);
      dist[s] = 0;
      priority_queue<pair<LL, int>> pq;
      pq.emplace(0, s);
      while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        d = -d;
        if (dist[u] < d) continue;
        for (int i = 0; i < (int)adj[u].size(); ++i) {
          auto &e = adj[u][i];
          if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost + potential[u] - potential[e.to]) {
            dist[e.to] = dist[u] + e.cost + potential[u] - potential[e.to];
            parent[e.to] = u;
            parent_edge[e.to] = i;
            pq.emplace(-dist[e.to], e.to);
          }
        }
      }
      if (dist[t] == INF) return -1;
      for (int i = 0; i < n; ++i) potential[i] += dist[i];
      LL flow_to_add = flow_req;
      for (int v = t; v != s; v = parent[v]) {
        flow_to_add = min(flow_to_add, adj[parent[v]][parent_edge[v]].capacity);
      }
      flow_req -= flow_to_add;
      total_cost += flow_to_add * potential[t];
      for (int v = t; v != s; v = parent[v]) {
        auto &e = adj[parent[v]][parent_edge[v]];
        e.capacity -= flow_to_add;
        adj[v][e.rev_idx].capacity += flow_to_add;
      }
    }
    return total_cost;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  LL N, M, K, C, D;
  cin >> N >> M >> K >> C >> D;
  vector<int> A(K);
  loop(i, K) cin >> A[i], A[i]--;
  vector<int> us(M), vs(M);
  loop(i, M) {
    cin >> us[i] >> vs[i];
    us[i]--;
    vs[i]--;
  }
  FlowNetwork network(N * 101 + 2);
  int s = N * 101;
  int t = s + 1;
  loop(i, K) {
    network.connect(s, A[i], 1, 0);
  }
  for (int i = 0; i <= 100; ++i) {
    network.connect(N * i, t, K, C * i);
  }
  for (int i = 0; i < 100; ++i) {
    for (int j = 0; j < N; ++j) {
      network.connect(i * N + j, (i + 1) * N + j, K, 0);
    }
    for (int j = 0; j < M; ++j) {
      for (int k = 1; k <= K; ++k) {
        network.connect(N * i + us[j], N * (i + 1) + vs[j], 1, (2 * k - 1) * D);
        network.connect(N * i + vs[j], N * (i + 1) + us[j], 1, (2 * k - 1) * D);
      }
    }
  }
  cout << network.min_cost_flow(s, t, K) << '\n';
}
